function fullRows(n: number): number {
  let lo = 0, hi = 65536;
  while (lo < hi) {
    const mid = Math.floor((lo + hi + 1) / 2); // upper middle so lo = mid always moves
    if ((mid * (mid + 1)) / 2 <= n) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

